<script setup>import{ ref} from 'vue'const produtos=ref([])const nome=ref('')const valor=ref('')function adicionarProduto(){ produtos.value.push({ nome: nome.value, valor: valor.value,}) nome.value='' valor.value=''}</script><template><div class="container border mt-4 p-4"><div class="d-flex justify-content-between align-items-center mb-3"><h1>produtos</h1><button class="btn btn-success" @click="adicionarProduto">Adicionar</button></div><div class="row mb-3"><div class="col"><input type="text" v-model="nome" class="form-control" placeholder="Nome do produto" /></div><div class="col"><input type="number" v-model="valor" class="form-control" placeholder="valor" /></div></div><div class="card"><div class="card-body"><table class="table table-striped"><thead class="table-light"><tr><th>Nome</th><th>valor</th></tr></thead><tbody><tr v-for="(produto, index) in produtos" :key="index"><td>{{ produto.nome}}</td><td>{{ produto.valor}}</td></tr></tbody></table></div></div></div></template>